import{_ as t,c as a,o,ah as p,ao as s,ap as i}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"牠會在那裡嗎？——聖經裡關於動物與天堂的盼望","description":"失去寵物後最深的疑問：牠會在天堂嗎？羅馬書、以賽亞書與啟示錄給了我們什麼盼望？","frontmatter":{"title":"牠會在那裡嗎？——聖經裡關於動物與天堂的盼望","description":"失去寵物後最深的疑問：牠會在天堂嗎？羅馬書、以賽亞書與啟示錄給了我們什麼盼望？"},"headers":[],"relativePath":"pets-in-heaven/will-i-see-my-pet-again.md","filePath":"pets-in-heaven/will-i-see-my-pet-again.md"}'),l={name:"pets-in-heaven/will-i-see-my-pet-again.md"};function n(r,e,h,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>「我知道自己會去天堂。我只是很想知道——牠會不會也在那裡等我？」</p><p class="pl-quote-soft">這是失去動物同伴的人，最常問、也最難問出口的問題。</p></div><section class="pl-section"><h2>先說一句誠實的話</h2><p>聖經沒有寫下「每一隻寵物都會在天堂與主人重逢」這樣的一節經文。任何人若把話說得太滿，其實是超過了聖經所說的。</p><p>但也請不要因此覺得絕望。因為聖經所描繪的圖畫，比我們以為的更寬闊：神的救贖從來不只是「把一些人類的靈魂救出來」，而是<strong>整個受造界的更新</strong>——而動物，從頭到尾都在那幅圖畫裡。</p></section><section class="pl-section"><h2>一、受造之物，與我們一同等候</h2><blockquote><p><strong>羅馬書 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>保羅在這裡說的，是一件很震撼的事：不只是人在嘆息等候，<em>受造之物</em>也一同嘆息、一同等候得贖。牠們不是被留在救恩之外的佈景，而是與我們一起望向同一個結局。</p><p>當你說「牠那麼善良，牠不該就這樣消失」，你所感受到的，和整個受造界所感受的是同一件事。聖經說，那份不甘心，最後會被回應。</p></section><section class="pl-section"><h2>二、神將要造的世界裡，有動物</h2><blockquote><p><strong>以賽亞書 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>先知以賽亞所看見的未來，不是一個只有光與雲的世界。他看見的是狼、羊羔、豹、山羊、牛犢與獅子，一個不再互相傷害、可以安然躺臥的世界。</p><p>如果神的心意只是「動物在今生用完就算了」，祂不必在應許裡為牠們留位置。祂留了。</p><p>而啟示錄在描述新天新地時也說：</p><blockquote><p><strong>啟示錄 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>「不再有死亡」是給整個受造界的宣告。你的牠所經歷的死亡，也是那將要被廢去的一件事。</p></section><section class="pl-section"><h2>三、所以，我們可以盼望到什麼程度？</h2><p>我們可以盼望，因為神是不撇下祂所造之物的神。我們可以盼望，因為基督的復活是新創造的初熟果子，而新創造的範圍，聖經說是「一切」。我們可以盼望，因為那位創造動物、喜悅動物的神，不會忽然變得不在意牠們。</p><p>至於「是不是同一隻」「牠還記不記得我」——聖經沒有給我們細節。它給我們的是一位可信的神，而細節在祂手中。這份留白不是要折磨我們，而是要我們把不能確定的事，交在那位良善的神手裡。</p><p class="pl-quote-soft">如果你願意，可以這樣禱告：</p></section><div class="pl-quote"><p>「主啊，我不知道天堂的細節，但我相信祢是良善的。<br>祢創造了牠，祢看顧了牠的每一天，祢也看見我此刻的眼淚。<br>我把牠交在祢手裡——正如我把自己交在祢手裡。<br>如果祢的應許裡有牠的位置，我為此感謝祢；<br>如果有人要替我照顧牠，那個人是祢，我就放心了。阿們。」</p></div><section class="pl-section"><h2>給今天特別難過的你</h2><p>詩篇的作者說：「耶和華救護人和牲畜」（詩篇 36:6）。這句話很短，卻是聖經裡極少數直接把動物放進神救護範圍的經文之一。</p><p>你的牠屬於那位「救護人和牲畜」的神。今天你所需要的，可能不是一個完整的答案，而是知道這件事：牠在神手中，而神是好的。</p><p><a href="/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 下一篇：<a href="/pets-in-heaven/not-one-sparrow-forgotten">連一隻麻雀，祂都記得</a></p></section><div class="pl-cta"><h2>把牠的名字寫下來。</h2><p>把牠的名字、牠最喜歡的位置、你還沒說出口的那句話寫下來。PetLoss 是一個私密的空間，不上傳、不催促，陪你慢慢整理。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下載</a></div><div class="pl-bible"><h3>讓聖經的話繼續陪你</h3><p>本文引用的經文都出自聖經。用《彩虹聖經》隨時閱讀神的話、設定每日經文小工具，在想念牠的日子裡仍有一盞燈。</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Rainbow Bible 聖經小工具顯示 2 Timothy 2:13" loading="lazy"><figcaption>每日經文放在主畫面</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible App 的「天堂裡的毛孩」主題，顯示 Matthew 10:29-31" loading="lazy"><figcaption>切換到「天堂裡的毛孩」主題讀經</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 取得《彩虹聖經》</a></div>',9)])])}const u=t(l,[["render",n]]);export{m as __pageData,u as default};
